@Override
public void close() throws IOException {
    if (closed) {
        return;
    }
    closed = true;
    memoryBuffer = null;
    if (spillOutputStream != null) {
        spillOutputStream.close();
        spillOutputStream = null;
    }
    // spillFile cleanup is handled by TemporaryResources
}
